// client/src/api/rouletteApi.js

import axios from 'axios';

// 🚨 백엔드 API의 기본 경로를 설정합니다. (프록시 설정에 따라 /api만 사용하거나 전체 URL을 사용합니다.)
const API_URL = '/api/roulette'; 

// 토큰을 포함한 설정을 가져오는 유틸리티 함수 (AuthContext에서 가져온다고 가정)
const getAuthHeaders = () => {
    const token = localStorage.getItem('token'); 
    return {
        headers: {
            Authorization: token ? `Bearer ${token}` : null,
        },
    };
};

/**
 * 룰렛 보상 목록을 가져옵니다. (GET /api/roulette/rewards)
 */
export const getRouletteRewards = async () => {
    const response = await axios.get(`${API_URL}/rewards`);
    return response.data;
};

/**
 * 룰렛을 실행하고 보상을 받습니다. (POST /api/roulette/spin)
 * @param {string} token - 인증 JWT 토큰
 */
export const spinRoulette = async () => {
    const config = getAuthHeaders();
    if (!config.headers.Authorization) {
        throw new Error("로그인 토큰이 없습니다.");
    }
    
    // POST 요청 본문은 비어 있습니다.
    const response = await axios.post(`${API_URL}/spin`, {}, config);
    return response.data;
};
